// Marshal serializes a Go value as a TOML document.
//
// It is a shortcut for Encoder.Encode() with the default options.
func Marshal(v interface{}) ([]byte, error) {
	enc := Encoder{indentSymbol: "  "}

	e := encoderStatePool.Get().(*encoderState)
	e.Encoder = &enc
	e.buf = e.buf[:0]
	e.keyStack = e.keyStack[:0]
	e.lastWasHeader = false

	err := e.encodeRoot(v)
	if err != nil {
		encoderStatePool.Put(e)
		return nil, err
	}

	out := make([]byte, len(e.buf))
	copy(out, e.buf)
	encoderStatePool.Put(e)
	return out, nil
}

// Encoder writes a TOML document to an output stream.
type Encoder struct {
	// output
	w io.Writer

	// global settings
	tablesInline       bool
	arraysMultiline    bool
	indentSymbol       string
	indentTables       bool
	marshalJSONNumbers bool
}

// NewEncoder returns a new Encoder that writes to w.
func NewEncoder(w io.Writer) *Encoder {
	return &Encoder{
		w:            w,
		indentSymbol: "  ",
	}
}

// SetTablesInline forces the encoder to emit all tables inline.
//
// This behavior can be controlled on an individual struct field basis with
// the inline tag:
//
//	MyField `toml:",inline"`
func (enc *Encoder) SetTablesInline(inline bool) *Encoder {
	enc.tablesInline = inline
	return enc
}

// SetArraysMultiline forces the encoder to emit all arrays with one element
// per line.
//
// This behavior can be controlled on an individual struct field basis with
// the multiline tag:
//
//	MyField `multiline:"true"`
func (enc *Encoder) SetArraysMultiline(multiline bool) *Encoder {
	enc.arraysMultiline = multiline
	return enc
}

// SetIndentSymbol defines the string that should be used for indentation. The
// provided string is repeated for each indentation level. Defaults to two
// spaces.
func (enc *Encoder) SetIndentSymbol(s string) *Encoder {
	enc.indentSymbol = s
	return enc
}

// SetIndentTables forces the encoder to intent tables and array tables.
func (enc *Encoder) SetIndentTables(indent bool) *Encoder {
	enc.indentTables = indent
	return enc
}

// SetMarshalJSONNumbers forces the encoder to serialize `json.Number` as a
// float or integer instead of relying on TextMarshaler to emit a string.
//
// *Unstable:* This method does not follow the compatibility guarantees of
// semver. It can be changed or removed without a new major version being
// issued.
func (enc *Encoder) SetMarshalJSONNumbers(indent bool) *Encoder {
	enc.marshalJSONNumbers = indent
	return enc
}

// Encode writes a TOML representation of v to the stream.
//
// If v cannot be represented to TOML it returns an error.
//
// # Encoding rules
//
// A top level slice containing only maps or structs is encoded as [[table
// array]].
//
// All slices not matching rule 1 are encoded as [array]. As a result, any map
// or struct they contain is encoded as an {inline table}.
//
// Nil interfaces and nil pointers are not supported.
//
// Keys in key-values always have one part.
//
// Intermediate tables are always printed.
//
// By default, strings are encoded as literal string, unless they contain
// either a newline character or a single quote. In that case they are emitted
// as quoted strings.
//
// Unsigned integers larger than math.MaxInt64 cannot be encoded. Doing so
// results in an error. This rule exists because the TOML specification only
// requires parsers to support at least the 64 bits integer range. Allowing
// larger numbers would create non-standard TOML documents, which may not be
// readable (at best) by other implementations. To encode such numbers, a
// solution is a custom type that implements encoding.TextMarshaler.
//
// When encoding structs, fields are encoded in order of definition, with
// their exact name.
//
// Tables and array tables are separated by empty lines. However, consecutive
// subtables definitions are not. For example:
//
//	[top1]
//
//	[top2]
//	[top2.child1]
//
//	[[array]]
//
//	[[array]]
//	[array.child2]
//
// # Struct tags
//
// The encoding of each public struct field can be customized by the format
// string in the "toml" key of the struct field's tag. This follows
// encoding/json's convention. The format string starts with the name of the
// field, optionally followed by a comma-separated list of options. The name
// may be empty in order to provide options without overriding the default
// name.
//
// The "multiline" option emits strings as quoted multi-line TOML strings, and
// arrays with one element per line. For strings, it only takes effect when the
// value contains a newline; single-line values are emitted as regular strings.
// It has no effect on fields that would not be encoded as strings or arrays.
//
// The "inline" option turns fields that would be emitted as tables into
// inline tables instead. It has no effect on other fields.
//
// The "omitempty" option prevents empty values or groups from being emitted.
//
// The "omitzero" option prevents zero values or groups from being emitted.
//
// The "commented" option prefixes the value and all its children with a
// comment symbol.
//
// In addition to the "toml" tag struct tag, a "comment" tag can be used to
// emit a TOML comment before the value being annotated. Comments are ignored
// inside inline tables. For array tables, the comment is only present before
// the first element of the array.
func (enc *Encoder) Encode(v interface{}) error {
	e := encoderStatePool.Get().(*encoderState)
	e.Encoder = enc
	e.buf = e.buf[:0]
	e.keyStack = e.keyStack[:0]
	e.lastWasHeader = false

	err := e.encodeRoot(v)
	if err != nil {
		encoderStatePool.Put(e)
		return err
	}

	_, err = enc.w.Write(e.buf)
	encoderStatePool.Put(e)
	if err != nil {
		return fmt.Errorf("toml: cannot write: %w", err)
	}
	return nil
}

var encoderStatePool = sync.Pool{
	New: func() interface{} { return &encoderState{} },
}

type encoderState struct {
	*Encoder

	buf []byte

	// keyStack is the dotted key of the table being encoded, shared by the
	// whole encode as a stack. Each part carries whether it can be emitted
	// bare, computed once at push: nested table headers re-emit every parent
	// part.
	keyStack []keyStackPart

	// entriesPool recycles entry slices across tables of the same encode.
	entriesPool [][]entry

	// lastWasHeader is true when the last line written was a table header,
	// used to avoid empty lines between consecutive table definitions.
	lastWasHeader bool

	// stringKeyBuf is a reusable buffer to read string map keys without
	// allocating one per map.
	stringKeyBuf reflect.Value

	// mapIter is a reusable map iterator (one would otherwise be allocated
	// for every table). Safe to share: a map is fully iterated (entries are
	// buffered) before any nested table starts its own iteration.
	mapIter reflect.MapIter

	// propsMemo is a small MRU memo of encPropsForType lookups: the values
	// of a document hit the same few named types over and over, and the
	// global cache lookup costs an interface hash every time.
	propsMemo [16]struct {
		t reflect.Type
		p typeEncProps
	}
}

// propsFor returns the encoding properties of t, memoizing recent lookups of
// the types the builtin fast path of encPropsForType does not cover.
func (e *encoderState) propsFor(t reflect.Type) typeEncProps {
	if p, ok := builtinEncProps(t); ok {
		return p
	}
	if e.propsMemo[0].t == t {
		return e.propsMemo[0].p
	}
	for i := 1; i < len(e.propsMemo); i++ {
		if e.propsMemo[i].t == t {
			m := e.propsMemo[i]
			copy(e.propsMemo[1:i+1], e.propsMemo[:i])
			e.propsMemo[0] = m
			return m.p
		}
	}
	p := encPropsForType(t)
	copy(e.propsMemo[1:], e.propsMemo[:len(e.propsMemo)-1])
	e.propsMemo[0].t, e.propsMemo[0].p = t, p
	return p
}

// valueOptions are the encoding options attached to one entry of a table.
type valueOptions struct {
	multiline bool
	inline    bool
	omitempty bool
	omitzero  bool
	commented bool
	comment   string
}

// entry is a deferred key-value of a table being encoded. Entries collected
// from a generic map[string]interface{} carry the value as anyValue (with a
// zero reflect.Value): the whole generic tree then encodes through concrete
// type switches, without reflection.
type entry struct {
	key      string
	value    reflect.Value
	anyValue interface{}
	// options points into the encoder plan (or at zeroValueOptions for map
	// entries): entries are copied around, and the options are the widest
	// part of them.
	options *valueOptions
	class   entryClass
	// pf points to the plan field the entry came from, carrying its
	// statically-known facts; nil for map entries.
	pf *encPlanField
}

// zeroValueOptions is the shared options of entries that have no tags.
var zeroValueOptions valueOptions

// entryClass tells how an entry of a table is emitted. It is computed once
// per entry: classifying requires resolving the value's type (and for arrays,
// the type of every element), which would otherwise be repeated by each of
// the encoding passes.
type entryClass uint8

const (
	classKeyValue entryClass = iota
	classTable
	classArrayTable
)

// classify computes the entryClass of an entry.
func (e *encoderState) classify(ent *entry) entryClass {
	if e.tablesInline || ent.options.inline {
		return classKeyValue
	}
	if ent.pf != nil && ent.pf.classKnown {
		return ent.pf.staticClass
	}
	if ent.anyValue != nil {
		switch v := ent.anyValue.(type) {
		case map[string]interface{}:
			return classTable
		case []interface{}:
			if len(v) == 0 {
				return classKeyValue
			}
			for _, elem := range v {
				if _, ok := elem.(map[string]interface{}); !ok {
					// Mixed or exotic elements: decide like the reflection
					// path would (resolving pointers and interfaces).
					if e.isArrayOfTables(reflect.ValueOf(ent.anyValue)) {
						return classArrayTable
					}
					return classKeyValue
				}
			}
			return classArrayTable
		case time.Time, LocalDate, LocalTime, LocalDateTime:
			return classKeyValue
		default:
			// Not a generic container: classify through reflection.
			v2 := reflect.ValueOf(ent.anyValue)
			if e.isArrayOfTables(v2) {
				return classArrayTable
			}
			if e.isTableLike(v2) {
				return classTable
			}
			return classKeyValue
		}
	}
	if e.isArrayOfTables(ent.value) {
		return classArrayTable
	}
	if e.isTableLike(ent.value) {
		return classTable
	}
	return classKeyValue
}

func (e *encoderState) encodeRoot(v interface{}) error {
	if v == nil {
		return errors.New("toml: cannot encode a nil interface")
	}

	if m, ok := v.(map[string]interface{}); ok {
		// Generic documents skip reflection entirely: their entries are
		// collected natively and every value encodes by type switch.
		entries := e.getEntries()
		for key, value := range m {
			if value == nil {
				// nil interface values are skipped
				continue
			}
			entries = append(entries, entry{key: key, anyValue: value, options: &zeroValueOptions})
		}
		if len(entries) > 1 {
			slices.SortFunc(entries, func(a, b entry) int {
				return strings.Compare(a.key, b.key)
			})
		}
		return e.encodeEntries(entries, false, 0)
	}

	rv := reflect.ValueOf(v)
	rv, ok := resolve(rv)
	if !ok {
		return errors.New("toml: cannot encode a nil pointer")
	}

	switch rv.Kind() {
	case reflect.Map, reflect.Struct:
		if isValueKind(rv) {
			return fmt.Errorf("toml: cannot encode a %s as a document root", rv.Type())
		}
		return e.encodeTable(rv, false, 0)
	default:
		return fmt.Errorf("toml: cannot encode a %s as a document root", rv.Type())
	}
}

// resolve unwraps pointers and interfaces until a concrete value is found.
// Returns false if it resolves to nil.
func resolve(v reflect.Value) (reflect.Value, bool) {
	for {
		switch v.Kind() {
		case reflect.Ptr:
			if v.IsNil() {
				return v, false
			}
			v = v.Elem()
		case reflect.Interface:
			if v.IsNil() {
				return v, false
			}
			v = v.Elem()
		default:
			return v, true
		}
	}
}

// typeEncProps caches the per-type facts used on every value encode.
type typeEncProps struct {
	// 0: not a TextMarshaler, 1: the type implements it, 2: its pointer does
	text uint8
	// encoded as a TOML value (as opposed to a table)
	isValue bool
}

var typeEncPropsCache sync.Map // reflect.Type -> typeEncProps

// builtinEncProps resolves the encoding properties of the handful of builtin
// types that make up generic documents (map[string]interface{} trees), none
// of which can implement TextMarshaler, with a kind dispatch and one pointer
// comparison instead of a cache lookup.
func builtinEncProps(t reflect.Type) (typeEncProps, bool) {
	switch t.Kind() {
	case reflect.String:
		if t == stringType {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Bool:
		if t == boolType {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Int:
		if t == intType {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Int64:
		if t == int64Type {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Float64:
		if t == float64Type {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Slice:
		if t == sliceInterfaceType {
			return typeEncProps{isValue: true}, true
		}
	case reflect.Map:
		if t == mapStringInterfaceType {
			return typeEncProps{isValue: false}, true
		}
	}
	return typeEncProps{}, false
}

func encPropsForType(t reflect.Type) typeEncProps {
	if p, ok := builtinEncProps(t); ok {
		return p
	}
	if p, ok := typeEncPropsCache.Load(t); ok {
		return p.(typeEncProps)
	}
	var p typeEncProps
	switch {
	case t.Implements(textMarshalerType):
		p.text = 1
	case reflect.PtrTo(t).Implements(textMarshalerType):
		p.text = 2
	}
	switch t {
	case timeType, localDateType, localTimeType, localDateTimeType:
		p.isValue = true
	default:
		if p.text != 0 {
			p.isValue = true
		} else {
			switch t.Kind() {
			case reflect.Map, reflect.Struct:
				p.isValue = false
			default:
				p.isValue = true
			}
		}
	}
	typeEncPropsCache.Store(t, p)
	return p
}

// isValueKind returns true when the resolved value is encoded as a TOML
// value (as opposed to a table).
func isValueKind(v reflect.Value) bool {
	return encPropsForType(v.Type()).isValue
}

// isTableLike returns true when the value should be encoded as a table (or
// an array of tables for slices).
func (e *encoderState) isTableLike(v reflect.Value) bool {
	v, ok := resolve(v)
	if !ok {
		// Unresolvable values (interface-held nil pointers) are encoded as
		// the zero value of their element type by the value path.
		return false
	}
	return !e.propsFor(v.Type()).isValue
}

// isArrayOfTables returns true when the value is a non-empty slice or array
// containing only table-like values.
func (e *encoderState) isArrayOfTables(v reflect.Value) bool {
	v, ok := resolve(v)
	if !ok {
		return false
	}
	if v.Kind() != reflect.Slice && v.Kind() != reflect.Array {
		return false
	}
	if v.Len() == 0 {
		return false
	}
	for i := 0; i < v.Len(); i++ {
		elem, ok := resolve(v.Index(i))
		if !ok || e.propsFor(elem.Type()).isValue {
			return false
		}
	}
	return true
}

// encodeTable writes the content of a table at the given key path.
func (e *encoderState) encodeTable(v reflect.Value, commented bool, indent int) error {
	entries, err := e.collectEntries(v)
	if err != nil {
		return err
	}
	return e.encodeEntries(entries, commented, indent)
}

// encodeEntries writes the collected entries of a table in the two passes
// (key-values first, then sub-tables) and returns the entry slice to the
// pool.
func (e *encoderState) encodeEntries(entries []entry, commented bool, indent int) error {
	// First pass: emit all key-values; tables are handled by the second
	// pass.
	for i := range entries {
		ent := &entries[i]
		ent.class = e.classify(ent)
		if ent.class != classKeyValue {
			continue
		}
		err := e.encodeKeyValue(ent, commented, indent)
		if err != nil {
			return err
