		return nil, err
	}
	if _, err := d.seen.CheckKeyValue(d.keyParts); err != nil {
		return nil, d.fusedSeenError(rawKey, d.keyParts, err)
	}
	av, err := d.fusedScalar(kind, value)
	if err != nil {
		return nil, err
	}
	d.setFusedLeaf(cur, d.keyParts, av)
	return rest, nil
}

func (d *decoder) replayFusedOps() error {
	if len(d.fusedOps) == 0 {
		return nil
	}
	d.valSeen.Reset()
	d.idStack = d.idStack[:0]
	top := int32(0)
	for _, op := range d.fusedOps {
		switch op.op {
		case fusedOpKey:
			id, err := d.valSeen.CheckKeyValueUnder(top, d.fusedParts[op.lo:op.hi])
			if err != nil {
				return err
			}
			d.idStack = append(d.idStack, top)
			top = id
		case fusedOpAnon:
			d.idStack = append(d.idStack, top)
			top = d.valSeen.CreateAnonymous(top)
		default: // fusedOpPop
			top = d.idStack[len(d.idStack)-1]
			d.idStack = d.idStack[:len(d.idStack)-1]
		}
	}
	return nil
}

func (d *decoder) fusedValue(b []byte) (interface{}, []byte, error) {
	switch b[0] {
	case '[', '{':
		return d.fusedContainerValue(b)
	default:
		k, _, value, rest, err := parserbridge.ScanScalar(&d.p, b)
		if err != nil {
			return nil, nil, err
		}
		av, err := d.fusedScalar(unstable.Kind(k), value)
		if err != nil {
			return nil, nil, err
		}
		return av, rest, nil
	}
}

func (d *decoder) fusedArray(b []byte) (interface{}, []byte, error) {
	b = b[1:]
	base := len(d.anyStack)
	afterValue := false
	for {
		b = fusedSkipWS(b)
		if len(b) == 0 {
			return nil, nil, unstable.NewParserError(b, "array is incomplete")
		}
		switch b[0] {
		case ']':
			elems := d.anyStack[base:]
			out := make([]interface{}, len(elems))
			copy(out, elems)
			clear(elems)
			d.anyStack = d.anyStack[:base]
			return out, b[1:], nil
		case '\n':
			b = b[1:]
		case '\r':
			if len(b) > 1 && b[1] == '\n' {
				b = b[2:]
				continue
			}
			return nil, nil, unstable.NewParserError(b[:1], "expected newline but got %#U", b[0])
		case '#':
			_, rest, err := parserbridge.ScanComment(b)
			if err != nil {
				return nil, nil, err
			}
			b = rest
		case ',':
			if !afterValue {
				return nil, nil, unstable.NewParserError(b[:1], "expected value but got %#U", b[0])
			}
			afterValue = false
			b = b[1:]
		default:
			if afterValue {
				return nil, nil, unstable.NewParserError(b[:1], "expected ',' or ']' after array value")
			}
			var (
				v   interface{}
				err error
			)
			if b[0] == '{' {
				// An inline table in an array is its own key scope.
				d.fusedOps = append(d.fusedOps, fusedOp{op: fusedOpAnon})
				v, b, err = d.fusedInlineTable(b)
				if err == nil {
					d.fusedOps = append(d.fusedOps, fusedOp{op: fusedOpPop})
				}
			} else {
				v, b, err = d.fusedValue(b)
			}
			if err != nil {
				return nil, nil, err
			}
			d.anyStack = append(d.anyStack, v)
			afterValue = true
		}
	}
}

func (d *decoder) fusedInlineTable(b []byte) (interface{}, []byte, error) {
	b = b[1:]
	base := len(d.kvStack)
	afterValue := false
	for {
		b = fusedSkipWS(b)
		if len(b) == 0 {
			return nil, nil, unstable.NewParserError(b, "inline table is incomplete")
		}
		switch b[0] {
		case '}':
			pairs := d.kvStack[base:]
			m := make(map[string]interface{}, len(pairs))
			for i := range pairs {
				kv := &pairs[i]
				parts := d.fusedParts[kv.lo:kv.hi]
				cur := m
				for j := 0; j < len(parts)-1; j++ {
					cur = d.anyChildTable(cur, d.intern(parts[j]))
				}
				cur[d.intern(parts[len(parts)-1])] = kv.v
			}
			clear(pairs)
			d.kvStack = d.kvStack[:base]
			return m, b[1:], nil
		case '\n':
			b = b[1:]
		case '\r':
			if len(b) > 1 && b[1] == '\n' {
				b = b[2:]
				continue
			}
			return nil, nil, unstable.NewParserError(b[:1], "expected newline but got %#U", b[0])
		case '#':
			_, rest, err := parserbridge.ScanComment(b)
			if err != nil {
				return nil, nil, err
			}
			b = rest
		case ',':
			if !afterValue {
				return nil, nil, unstable.NewParserError(b[:1], "unexpected comma in inline table")
			}
			afterValue = false
			b = b[1:]
		default:
			if afterValue {
				return nil, nil, unstable.NewParserError(b[:1], "expected ',' or '}' after inline table key-value")
			}
			var err error
			b, err = d.fusedInlineKeyval(b)
			if err != nil {
				return nil, nil, err
			}
			afterValue = true
		}
	}
}

func (d *decoder) fusedInlineKeyval(b []byte) ([]byte, error) {
	save := len(d.fusedParts)
	var err error
	d.fusedParts, _, b, err = parserbridge.ScanKey(&d.p, b, d.fusedParts)
	if err != nil {
		return nil, err
	}
	if len(b) == 0 || b[0] != '=' {
		return nil, unstable.NewParserError(fusedHL1(b), "expected '=' after key")
	}
	b = fusedSkipWS(b[1:])
	if len(b) == 0 {
		return nil, unstable.NewParserError(b, "expected value, not end of input")
	}

	// The parts range must be pinned before parsing the value: the keys of a
	// nested inline table extend d.fusedParts.
	lo := int32(save)              //nolint:gosec // part counts are bounded by document size
	hi := int32(len(d.fusedParts)) //nolint:gosec // part counts are bounded by document size
	d.fusedOps = append(d.fusedOps, fusedOp{op: fusedOpKey, lo: lo, hi: hi})
	v, b, err := d.fusedValue(b)
	if err != nil {
		return nil, err
	}
	d.fusedOps = append(d.fusedOps, fusedOp{op: fusedOpPop})

	d.kvStack = append(d.kvStack, fusedKV{v: v, lo: lo, hi: hi})
	return b, nil
}

func (d *decoder) fusedSeenError(rawKey []byte, parts [][]byte, err error) error {
	key := make(Key, len(parts))
	for i, p := range parts {
		key[i] = string(p)
	}
	return &unstable.ParserError{
		Highlight: rawKey,
		Message:   strings.TrimPrefix(err.Error(), "toml: "),
		Key:       key,
	}
}

func (d *decoder) fusedScalar(kind unstable.Kind, value []byte) (interface{}, error) {
	switch kind {
	case unstable.String:
		return string(value), nil
	case unstable.Integer:
		i, err := parseInteger(value)
		return i, err
	case unstable.Float:
		f, err := parseFloat(value)
		return f, err
	case unstable.Bool:
		return value[0] == 't', nil
	case unstable.DateTime:
		t, err := parseDateTime(value)
		return t, err
	case unstable.LocalDateTime:
		dt, rest, err := parseLocalDateTime(value)
		if err != nil {
			return nil, err
		}
		if len(rest) > 0 {
			return nil, unstable.NewParserError(rest, "extra characters at the end of a local date time")
		}
		return dt, nil
	case unstable.LocalDate:
		date, err := parseLocalDate(value)
		return date, err
	case unstable.LocalTime:
		t, rest, err := parseLocalTime(value)
		if err != nil {
			return nil, err
		}
		if len(rest) > 0 {
			return nil, unstable.NewParserError(rest, "extra characters at the end of a local time")
		}
		return t, nil
	default:
		return nil, unstable.NewParserError(value, "unsupported value kind %s", kind)
	}
}

func (d *decoder) anyTableParts(m map[string]interface{}, parts [][]byte) map[string]interface{} {
	cur := m
	for _, p := range parts {
		cur = d.anyChildTable(cur, d.intern(p))
	}
	return cur
}

func (d *decoder) anyArrayTableParts(m map[string]interface{}, parts [][]byte, first bool) map[string]interface{} {
	cur := m
	name := d.intern(parts[0])
	for i := 1; i < len(parts); i++ {
		cur = d.anyChildTable(cur, name)
		name = d.intern(parts[i])
	}
	s, _ := cur[name].([]interface{})
	if first {
		s = s[:0]
	}
	elem := map[string]interface{}{}
	cur[name] = append(s, elem)
	return elem
}

func (d *decoder) setFusedLeaf(cur map[string]interface{}, parts [][]byte, av interface{}) {
	for i := 0; i < len(parts)-1; i++ {
		cur = d.anyChildTable(cur, d.intern(parts[i]))
	}
	cur[d.intern(parts[len(parts)-1])] = av
}

func (d *decoder) wrapFusedError(data []byte, err error) error {
	var perr *unstable.ParserError
	if errors.As(err, &perr) && len(perr.Highlight) == 0 {
		// Mirror NextExpression: give end-of-input errors a usable position by
		// extending the empty highlight to the last byte of the document.
		if offset := cap(data) - cap(perr.Highlight); offset > 0 && offset == len(data) {
			perr.Highlight = data[offset-1 : offset]
		}
	}
	return d.wrapError(data, err)
}

func fusedSkipWS(b []byte) []byte {
	for len(b) > 0 && (b[0] == ' ' || b[0] == '\t') {
		b = b[1:]
	}
	return b
}

func fusedConsumeEOL(b []byte) ([]byte, error) {
	if len(b) == 0 {
		return b, nil
	}
	switch b[0] {
	case '\n':
		return b[1:], nil
	case '\r':
		if len(b) > 1 && b[1] == '\n' {
			return b[2:], nil
		}
	}
	return nil, unstable.NewParserError(b[:1], "expected newline but got %#U", b[0])
}

func (d *decoder) fusedFinishLine(b []byte) ([]byte, error) {
	b = fusedSkipWS(b)
	if len(b) > 0 && b[0] == '#' {
		_, rest, err := parserbridge.ScanComment(b)
		if err != nil {
			return nil, err
		}
		b = rest
	}
	return fusedConsumeEOL(b)
}

func fusedHL1(b []byte) []byte {
	if len(b) > 0 {
		return b[:1]
	}
	return b
}

func (d *decoder) fusedStructDocument(root reflect.Value, data []byte) error {
	b := data
	for {
		b = fusedSkipWS(b)
		if len(b) == 0 {
			return nil
		}
		switch b[0] {
		case '\n':
			b = b[1:]
		case '\r':
			if len(b) > 1 && b[1] == '\n' {
				b = b[2:]
				continue
			}
			return d.wrapFusedError(data, unstable.NewParserError(b[:1], "expected newline but got %#U", b[0]))
		case '#':
			_, rest, err := parserbridge.ScanComment(b)
			if err == nil {
				rest, err = fusedConsumeEOL(rest)
			}
			if err != nil {
				return d.wrapFusedError(data, err)
			}
			b = rest
		case '[':
			// Table headers run through the expression parser and the
			// regular handling (seen-tracking, strict bookkeeping, walk).
			parserbridge.SetCursor(&d.p, b)
			if !d.p.NextExpression() {
				if err := d.p.Error(); err != nil {
					var perr *unstable.ParserError
					if errors.As(err, &perr) {
						return wrapDecodeError(data, perr)
					}
					return err
				}
				return nil
			}
			if err := d.handleRootExpression(d.p.Expression(), root); err != nil {
				return d.wrapError(data, err)
			}
			b = parserbridge.Cursor(&d.p)
		default:
			rest, err := d.fusedStructKeyVal(b, root)
			if err != nil {
				return d.wrapFusedError(data, err)
			}
			b = rest
		}
	}
}

func (d *decoder) fusedStructKeyVal(b []byte, root reflect.Value) ([]byte, error) {
	var err error
	var rawKey []byte
	d.keyParts, d.keyRaws, rawKey, b, err = parserbridge.ScanKeyRaws(&d.p, b, d.keyParts[:0], d.keyRaws[:0])
	if err != nil {
		return nil, err
	}
	if len(b) == 0 || b[0] != '=' {
		return nil, unstable.NewParserError(fusedHL1(b), "expected '=' after key")
	}
	b = fusedSkipWS(b[1:])
	if len(b) == 0 {
		return nil, unstable.NewParserError(b, "expected value, not end of input")
	}

	if c := b[0]; c == '[' || c == '{' {
		valStart := b
		nodeAny, rest, err := parserbridge.ParseValue(&d.p, b)
		if err != nil {
			return nil, err
		}
		node := nodeAny.(*unstable.Node)
		valSpan := valStart[:len(valStart)-len(rest)]
		rest, err = d.fusedFinishLine(rest)
		if err != nil {
			return nil, err
		}
		if _, err := d.seen.CheckKeyValue(d.keyParts); err != nil {
			return nil, d.fusedSeenError(rawKey, d.keyParts, err)
		}
		if err := d.validateValueNode(node); err != nil {
			return nil, d.fusedSeenError(rawKey, d.keyParts, err)
		}
		if d.skipUntilTable {
			return rest, nil
		}
		d.fusedValueSpan = valSpan
		err = d.fusedHandleKeyValue(root, rawKey, node)
		d.fusedValueSpan = nil
		return rest, err
	}

	// Scalar value: no AST at all. The stack node carries the same kind,
	// data, and raw range an arena node would; nothing retains it.
	k, rawVal, value, rest, err := parserbridge.ScanScalar(&d.p, b)
	if err != nil {
		return nil, err
	}
	rest, err = d.fusedFinishLine(rest)
	if err != nil {
		return nil, err
	}
	if _, err := d.seen.CheckKeyValue(d.keyParts); err != nil {
		return nil, d.fusedSeenError(rawKey, d.keyParts, err)
	}
	if d.skipUntilTable {
		return rest, nil
	}
	node := unstable.Node{
		Kind: unstable.Kind(k),
		Raw:  d.p.Range(rawVal),
		Data: value,
	}
	return rest, d.fusedHandleKeyValue(root, rawKey, &node)
}

func (d *decoder) fusedHandleKeyValue(root reflect.Value, rawKey []byte, value *unstable.Node) error {
	d.path = d.path[:0]

	target := root
	useCache := d.tableTargetValid && len(d.tableKey) > 0
	if useCache {
		target = d.tableTarget
	} else {
		for _, name := range d.tableKey {
			d.path = append(d.path, pathPart{name: name})
		}
	}
	for i := range d.keyParts {
		d.path = append(d.path, pathPart{data: d.keyParts[i], rng: d.p.Range(d.keyRaws[i])})
	}
	d.fusedKVParts = d.keyParts
	d.fusedKVKeyRange = d.p.Range(rawKey)

	nv, err := d.descend(target, d.path, 0, nil, value)
	if err != nil {
		return d.contextualizeError(err, useCache)
	}
	if !nv.IsValid() {
		return nil
	}
	if useCache {
		// The target may have been replaced (e.g. a nil map allocated):
		// re-link it into its parent.
		if nv.Kind() == reflect.Map && nv.Pointer() != d.tableTarget.Pointer() {
			d.storeSlot(&d.tableParentSlot, nv)
			d.tableTarget = nv
		}
	} else {
		if root.CanSet() {
			root.Set(nv)
		}
	}
	return nil
}

func parseInteger(b []byte) (int64, error) {
	if len(b) > 2 && b[0] == '0' {
		switch b[1] {
		case 'x':
			return parseIntHex(b)
		case 'b':
			return parseIntBin(b)
		case 'o':
			return parseIntOct(b)
		default:
			panic(fmt.Errorf("invalid base '%c', should have been checked by scanIntOrFloat", b[1]))
		}
	}
	return parseIntDec(b)
}

func parseIntDec(b []byte) (int64, error) {
	i := 0
	neg := false
	switch b[0] {
	case '-':
		neg = true
		i++
	case '+':
		i++
	}

	var limit uint64 = math.MaxInt64
	if neg {
		limit = math.MaxInt64 + 1
	}

	var v uint64
	for ; i < len(b); i++ {
		c := b[i]
		if c == '_' {
			continue
		}
		if v > limit/10 {
			return 0, unstable.NewParserError(b, "decimal number is too large to fit in a 64-bit signed integer")
		}
		v = v*10 + uint64(c-'0')
		if v > limit {
			return 0, unstable.NewParserError(b, "decimal number is too large to fit in a 64-bit signed integer")
		}
	}
	if neg {
		return -int64(v), nil //nolint:gosec // v <= MaxInt64+1, the conversion wraps to the intended negative value
	}
	return int64(v), nil //nolint:gosec // v <= MaxInt64
}

func parseFloat(b []byte) (float64, error) {
	i := 0
	if len(b) > 0 && (b[0] == '+' || b[0] == '-') {
		i = 1
	}
	if len(b) == i+3 {
		switch b[i] {
		case 'i':
			// inf
			if b[0] == '-' {
				return math.Inf(-1), nil
			}
			return math.Inf(1), nil
		case 'n':
			// nan
			return math.NaN(), nil
		}
	}

	// Fast path: a plain decimal whose significand fits in 53 bits and whose
	// base-10 exponent is within [-22, 22] is parsed exactly with a single
	// rounding (Clinger's method) straight from the bytes, with no string
	// allocation and no full strconv parse. This is the common shape for
	// numeric data (e.g. coordinate lists). Anything outside those bounds, or
	// with underscores, falls through to strconv, which is the reference.
	if f, ok := fastParseFloat(b); ok {
		return f, nil
	}

	// strconv.ParseFloat is the reference implementation for parsing
	// floating point numbers. The position of underscores has already been
	// validated by the parser; strip them so that they do not interfere with
	// Go's own underscore rules.
	cleaned := b
	if bytes.IndexByte(b, '_') >= 0 {
		cleaned = make([]byte, 0, len(b))
		for _, c := range b {
			if c != '_' {
				cleaned = append(cleaned, c)
			}
		}
	}

	f, err := strconv.ParseFloat(string(cleaned), 64)
	if err != nil {
		return 0, unstable.NewParserError(b, "unable to parse float: %s", err)
	}
	return f, nil
}

func fastParseFloat(b []byte) (float64, bool) {
	i := 0
	neg := false
	if i < len(b) && (b[i] == '+' || b[i] == '-') {
		neg = b[i] == '-'
		i++
	}

	var mantissa uint64
	digits := 0
	fracDigits := 0
	sawDot := false
	sawDigit := false
	for ; i < len(b); i++ {
		c := b[i]
		switch {
		case c >= '0' && c <= '9':
			if digits >= 19 {
				// Too many significant digits to accumulate without risking a
				// uint64 overflow (and well past the 53-bit exact range).
				return 0, false
			}
			mantissa = mantissa*10 + uint64(c-'0')
			digits++
			if sawDot {
				fracDigits++
			}
			sawDigit = true
		case c == '.':
			if sawDot {
				return 0, false
			}
			sawDot = true
		default:
			goto exponent
		}
	}
exponent:
	if !sawDigit {
		return 0, false
	}
	exp := -fracDigits
	if i < len(b) && (b[i] == 'e' || b[i] == 'E') {
		i++
		esign := 1
		if i < len(b) && (b[i] == '+' || b[i] == '-') {
			if b[i] == '-' {
				esign = -1
			}
			i++
		}
		if i >= len(b) {
			return 0, false
		}
		eval := 0
		for ; i < len(b); i++ {
			c := b[i]
			if c < '0' || c > '9' {
				return 0, false
			}
			eval = eval*10 + int(c-'0')
			if eval > 1000 {
				return 0, false
			}
		}
		exp += esign * eval
	}
	if i != len(b) {
		// Trailing bytes (an underscore, a hexadecimal marker, ...).
		return 0, false
	}

	var f float64
	switch {
	case mantissa <= 1<<53 && exp == 0:
		f = float64(mantissa)
	case mantissa <= 1<<53 && exp > 0 && exp <= 22:
		f = float64(mantissa) * float64pow10[exp]
	case mantissa <= 1<<53 && exp < 0 && exp >= -22:
		f = float64(mantissa) / float64pow10[-exp]
	case exp >= -27 && exp <= 27:
		// The significand does not fit in 53 bits (or the exponent is a bit
		// past the exact float64 powers of ten): compute the correctly
		// rounded result with exact 128-bit integer arithmetic.
		var ok bool
		f, ok = wideParseFloat(mantissa, exp)
		if !ok {
			return 0, false
		}
	default:
		return 0, false
	}
	if neg {
		f = -f
	}
	return f, true
}

func wideParseFloat(mantissa uint64, exp int) (float64, bool) {
	switch {
	case mantissa == 0:
		return 0, true
	case exp == 0:
		// Go guarantees correctly rounded uint64 to float64 conversions.
		return float64(mantissa), true
	case exp > 0:
		if exp >= len(uint64pow5) {
			return 0, false
		}
		// value = (mantissa * 5^exp) * 2^exp, with the product exact on 128
		// bits.
		hi, lo := bits.Mul64(mantissa, uint64pow5[exp])
		if hi == 0 {
			return roundFloat64(lo, exp, false), true
		}
		sh := uint(bits.Len64(hi))
		top := hi<<(64-sh) | lo>>sh
		sticky := lo<<(64-sh) != 0
		return roundFloat64(top, exp+int(sh), sticky), true
	default:
		p := -exp
		if p >= len(uint64pow5) {
			return 0, false
		}
		// value = (mantissa / 5^p) * 2^exp. Shift the mantissa up so the
		// 128/64-bit division yields a quotient with 55 to 63 significant
		// bits, then round with the exact remainder.
		d := uint64pow5[p]
		t := bits.Len64(d) + 58 - bits.Len64(mantissa)
		if t < 0 {
			t = 0
		}
		var hi, lo uint64
		if t >= 64 {
			hi, lo = mantissa<<(t-64), 0
		} else {
			hi, lo = mantissa>>(64-t), mantissa<<t
		}
		q, r := bits.Div64(hi, lo, d)
		return roundFloat64(q, exp-t, r != 0), true
	}
}

func parseLocalDate(b []byte) (LocalDate, error) {
	var date LocalDate

	if len(b) != 10 || b[4] != '-' || b[7] != '-' {
		return date, unstable.NewParserError(b, "dates are expected to have the format YYYY-MM-DD")
	}

	var err error
	date.Year, err = parseDecimalDigits(b[0:4])
	if err != nil {
		return date, err
	}
	date.Month, err = parseDecimalDigits(b[5:7])
	if err != nil {
		return date, err
	}
	date.Day, err = parseDecimalDigits(b[8:10])
	if err != nil {
		return date, err
	}

	if date.Month < 1 || date.Month > 12 {
		return date, unstable.NewParserError(b[5:7], "impossible date")
	}
	maxDay := daysIn(date.Month, date.Year)
	if date.Day < 1 || date.Day > maxDay {
		return date, unstable.NewParserError(b[8:10], "impossible date")
	}

	return date, nil
}

func parseDecimalDigits(b []byte) (int, error) {
	v := 0
	for i, c := range b {
		if !isDecimalDigit(c) {
			return 0, unstable.NewParserError(b[i:i+1], "expected digit (0-9)")
		}
		v = v*10 + int(c-'0')
	}
	return v, nil
}

